def main():
    raw = open(BASE, "rb").read()
    got = hashlib.sha256(raw).hexdigest()
    assert got == BASE_SHA, f"base sha mismatch: {got} != {BASE_SHA}"
    lines = raw.decode().splitlines(keepends=True)
    out = []
    pos = 0
    for tag, i1, i2, rep in OPS:
        out.extend(lines[pos:i1])
        if rep:
            out.append(rep)
        pos = i2
    out.extend(lines[pos:])
    res = "".join(out)

    # --- Post-steps: audit fixes (2026-11-20, R11-CODE-AUDIT-2026-11-20) ---
    # Exact-match patches on the generated text, count-asserted so base
    # drift stops the generator instead of silently dropping a fix. The
    # DST_SHA assert below pins the final text including these patches.
    def patch(old, new, count):
        assert res.count(old) == count, \
            f"patch anchor count {res.count(old)} != {count}: {old[:64]!r}"
        return res.replace(old, new)

    # (a) floatBucket12 comment: the negative-side fine range starts at
    # 2^-7, not 2^-8 (the band (-2^-7, +2^-8) is one coarse bin), and the
    # map is monotone non-decreasing, not strictly monotonic.
    res = patch(
        "// 6-bit mantissa precision (64 bins/exponent) across [-2^23, -2^-8] and [+2^-8, +2^23].\n"
        "// Strictly monotonic with 64-bit ordOfBits(double) for ALL uint64_t values!",
        "// 6-bit mantissa precision (64 bins/exponent) across [+2^-8, +2^23] and, on the\n"
        "// negative side, |d| in [2^-7, ~1.48*2^23); the band (-2^-7, +2^-8) collapses\n"
        "// into the single central bin 1921 (audit B (a)).\n"
        "// Monotone non-decreasing in 64-bit ordOfBits(double) for ALL uint64_t values.",
        1)
    res = patch("(negatives -2^23 .. -2^-8)",
                "(negatives, fine-grained for |d| in [2^-7, ~1.48*2^23))", 1)
    res = patch("// (-2^-8 .. +2^-8)", "// central coarse bin (-2^-7 .. +2^-8)", 1)

    # (b) CAND capacity guard. CAND occupies the EVLIST region
    # (EVORD - EVLIST = 16384 words; 3 words per entry -> 5461 entries).
    # Overflow used to spill into EVORD (PB_HIST) and corrupt silently.
    # Now writes are clamped to the region and overflow fails the
    # decision through the gbar error channel (ctrl[128] unwinds every
    # stage; ctrl[1] is the host-polled error word).
    res = patch("#define CAND_OFF  EVLIST\n",
                "#define CAND_OFF  EVLIST\n#define CAND_CAP  5461u\n", 1)
    res = patch(
        "        uint cs = atomicAdd(state.u[STATS + ST_CAND], 1u);\n"
        "        state.u[CAND_OFF + cs * 3u + 0u] = uint(ord >> 32);\n"
        "        state.u[CAND_OFF + cs * 3u + 1u] = uint(ord);\n"
        "        state.u[CAND_OFF + cs * 3u + 2u] = coff;\n",
        "        uint cs = atomicAdd(state.u[STATS + ST_CAND], 1u);\n"
        "        if (cs < CAND_CAP) {\n"
        "          state.u[CAND_OFF + cs * 3u + 0u] = uint(ord >> 32);\n"
        "          state.u[CAND_OFF + cs * 3u + 1u] = uint(ord);\n"
        "          state.u[CAND_OFF + cs * 3u + 2u] = coff;\n"
        "        } else { atomicOr(ctrl.u[128u], 1u); atomicOr(ctrl.u[1u], 1u); }\n",
        1)
    res = patch(
        "      uint cs = atomicAdd(state.u[STATS + ST_CAND], 1u);\n"
        "      state.u[CAND_OFF + cs * 3u + 0u] = uint(ord >> 32);\n"
        "      state.u[CAND_OFF + cs * 3u + 1u] = uint(ord);\n"
        "      state.u[CAND_OFF + cs * 3u + 2u] = coff;\n",
        "      uint cs = atomicAdd(state.u[STATS + ST_CAND], 1u);\n"
        "      if (cs < CAND_CAP) {\n"
        "        state.u[CAND_OFF + cs * 3u + 0u] = uint(ord >> 32);\n"
        "        state.u[CAND_OFF + cs * 3u + 1u] = uint(ord);\n"
        "        state.u[CAND_OFF + cs * 3u + 2u] = coff;\n"
        "      } else { atomicOr(ctrl.u[128u], 1u); atomicOr(ctrl.u[1u], 1u); }\n",
        1)
    # Keep merge-stage reads inside the region in a failed decision.
    res = patch("  uint nCand = state.u[STATS + ST_CAND];",
                "  uint nCand = min(state.u[STATS + ST_CAND], CAND_CAP);", 1)

    res_sha = hashlib.sha256(res.encode()).hexdigest()
    assert res_sha == DST_SHA, f"output sha mismatch: {res_sha} != {DST_SHA}"
    open(DST, "w").write(res)
    print("wrote", DST, "lines(wc)", res.count("\n"), "sha256", res_sha)

if __name__ == "__main__":
    main()
